A simple, responsive calculator with keyboard support.

<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Simple Calculator</title>
  <style>
    * { box-sizing: border-box; }
    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 1rem;
      background: #f1f5f9;
      color: #0f172a;
      font-family: system-ui, sans-serif;
    }
    .calculator {
      width: min(100%, 340px);
      padding: 1rem;
      border-radius: 1rem;
      background: #fff;
      box-shadow: 0 12px 32px #0f172a1a;
    }
    h1 { margin: 0 0 .75rem; font-size: 1.15rem; }
    .display {
      min-height: 4.5rem;
      margin-bottom: .75rem;
      padding: .75rem;
      display: flex;
      align-items: center;
      justify-content: flex-end;
      overflow: hidden;
      border-radius: .6rem;
      background: #e2e8f0;
      font-size: 2rem;
      font-variant-numeric: tabular-nums;
      overflow-wrap: anywhere;
    }
    .keys { display: grid; grid-template-columns: repeat(4, 1fr); gap: .5rem; }
    button {
      min-height: 3.25rem;
      border: 0;
      border-radius: .6rem;
      background: #f1f5f9;
      color: #0f172a;
      font: inherit;
      font-size: 1.1rem;
      cursor: pointer;
    }
    button:hover { background: #e2e8f0; }
    button:focus-visible { outline: 3px solid #2563eb; outline-offset: 2px; }
    .utility { background: #cbd5e1; }
    .operator, .equals { background: #2563eb; color: #fff; }
    .operator:hover, .equals:hover { background: #1d4ed8; }
    .zero { grid-column: span 2; }
  </style>
</head>
<body>
  <main class="calculator" aria-label="Calculator">
    <h1>Calculator</h1>
    <output class="display" id="display" aria-live="polite" aria-label="Display">0</output>
    <div class="keys">
      <button class="utility" type="button" data-action="clear" aria-label="Clear">AC</button>
      <button class="utility" type="button" data-action="delete" aria-label="Delete last digit">DEL</button>
      <button class="operator" type="button" data-op="÷" aria-label="Divide">÷</button>
      <button class="operator" type="button" data-op="×" aria-label="Multiply">×</button>
      <button type="button" data-digit="7">7</button>
      <button type="button" data-digit="8">8</button>
      <button type="button" data-digit="9">9</button>
      <button class="operator" type="button" data-op="−" aria-label="Subtract">−</button>
      <button type="button" data-digit="4">4</button>
      <button type="button" data-digit="5">5</button>
      <button type="button" data-digit="6">6</button>
      <button class="operator" type="button" data-op="+" aria-label="Add">+</button>
      <button type="button" data-digit="1">1</button>
      <button type="button" data-digit="2">2</button>
      <button type="button" data-digit="3">3</button>
      <button class="equals" type="button" data-action="equals" aria-label="Equals">=</button>
      <button class="zero" type="button" data-digit="0">0</button>
      <button type="button" data-action="decimal" aria-label="Decimal point">.</button>
    </div>
  </main>
  <script>
    const display = document.getElementById('display');
    let current = '0';
    let stored = null;
    let operator = null;
    let replaceCurrent = false;
    let justCalculated = false;

    function render() {
      display.textContent = current;
    }

    function formatResult(value) {
      if (!Number.isFinite(value)) return 'Error';
      return String(Number(value.toPrecision(12)));
    }

    function inputDigit(digit) {
      if (current === 'Error' || replaceCurrent || justCalculated) {
        current = digit;
        replaceCurrent = false;
        justCalculated = false;
      } else if (current === '0') {
        current = digit;
      } else if (current.length < 16) {
        current += digit;
      }
      render();
    }

    function inputDecimal() {
      if (current === 'Error' || replaceCurrent || justCalculated) {
        current = '0.';
        replaceCurrent = false;
        justCalculated = false;
      } else if (!current.includes('.')) {
        current += '.';
      }
      render();
    }

    function calculate(a, op, b) {
      if (op === '+') return a + b;
      if (op === '−') return a - b;
      if (op === '×') return a * b;
      if (op === '÷') return b === 0 ? NaN : a / b;
      return b;
    }

    function chooseOperator(nextOperator) {
      if (current === 'Error') return;
      const value = Number(current);
      if (operator && !replaceCurrent) {
        const result = calculate(stored, operator, value);
        current = formatResult(result);
        if (current === 'Error') {
          stored = null;
          operator = null;
          render();
          return;
        }
        stored = Number(current);
      } else {
        stored = value;
      }
      operator = nextOperator;
      replaceCurrent = true;
      justCalculated = false;
      render();
    }

    function equals() {
      if (!operator || stored === null || current === 'Error') return;
      const result = calculate(stored, operator, Number(current));
      current = formatResult(result);
      stored = null;
      operator = null;
      replaceCurrent = true;
      justCalculated = true;
      render();
    }

    function clear() {
      current = '0';
      stored = null;
      operator = null;
      replaceCurrent = false;
      justCalculated = false;
      render();
    }

    function deleteLast() {
      if (current === 'Error' || replaceCurrent || justCalculated) {
        current = '0';
        replaceCurrent = false;
        justCalculated = false;
      } else {
        current = current.length > 1 ? current.slice(0, -1) : '0';
        if (current === '-') current = '0';
      }
      render();
    }

    document.querySelector('.keys').addEventListener('click', (event) => {
      const button = event.target.closest('button');
      if (!button) return;
      if (button.dataset.digit !== undefined) inputDigit(button.dataset.digit);
      else if (button.dataset.op) chooseOperator(button.dataset.op);
      else if (button.dataset.action === 'decimal') inputDecimal();
      else if (button.dataset.action === 'equals') equals();
      else if (button.dataset.action === 'clear') clear();
      else if (button.dataset.action === 'delete') deleteLast();
    });

    document.addEventListener('keydown', (event) => {
      const key = event.key;
      if (/^[0-9]$/.test(key)) inputDigit(key);
      else if (key === '.') inputDecimal();
      else if (key === '+') chooseOperator('+');
      else if (key === '-') chooseOperator('−');
      else if (key === '*') chooseOperator('×');
      else if (key === '/') chooseOperator('÷');
      else if (key === 'Enter' || key === '=') equals();
      else if (key === 'Backspace') deleteLast();
      else if (key === 'Escape' || key.toLowerCase() === 'c') clear();
      else return;
      event.preventDefault();
    });
  </script>
</body>
</html>

